import {
  isBarCanvasEqual,
  barAnimation,
} from '../functions/animations/bar-canvas.js';
import { printBarBuilder } from '../functions/shapes/bar-canvas.js';
import { useCanvas } from '../hooks/useCanvas.js';
import { useCanvasAnimation } from '../hooks/useCanvasAnimation.js';
import {
  FnCanvasAccessor,
  BarCanvasProps,
  BarCanvasInstance,
} from '../types/canvas-shape.js';

export function BarCanvas<Datum>(props: BarCanvasProps<Datum>) {
  const {
    strokeWidth,
    isVertical = true,
    animation = { enabled: false },
    ...propsBarCanvas
  } = props;

  // Build how Line canvas should style
  const drawBars = printBarBuilder<Datum>(strokeWidth);

  // Define draw method for entire Bars shape
  const drawBarCanvas = (
    ctx: CanvasRenderingContext2D,
    canvas: BarCanvasInstance<Datum>,
  ) => {
    drawBars(ctx, canvas, canvas.x, canvas.y, canvas.width, canvas.height);
  };

  // Define draw tick per animation lap for Bars shape
  // TODO: ADES-4720 first chape from stacked bars appears as 0 when animating
  const onTickAnimation = (
    progress: number,
    ctx: CanvasRenderingContext2D,
    barCanvas: BarCanvasInstance<Datum>,
    prevCanvas?: BarCanvasInstance<Datum>,
  ) => {
    const barTick = (
      x: FnCanvasAccessor<Datum>,
      y: FnCanvasAccessor<Datum>,
      w: FnCanvasAccessor<Datum>,
      h: FnCanvasAccessor<Datum>,
    ) => drawBars(ctx, barCanvas, x, y, w, h);

    barAnimation(barCanvas, progress, barTick, prevCanvas);
  };

  const barCanvas = {
    ...propsBarCanvas,
    isVertical,
  };

  // Register shape/draw
  const { draw } = useCanvasAnimation<BarCanvasInstance<Datum>, Datum>(
    barCanvas,
    drawBarCanvas,
    animation.enabled ?? false,
    isBarCanvasEqual,
    onTickAnimation as any, // eslint-disable-line @typescript-eslint/no-explicit-any
    //TODO: ADES-3008 refactor animation,
    animation.duration,
  );

  useCanvas('bar', draw);

  return null;
}
